/**
 * What the platform host's `sitemap.xml` lists (owner decision D6).
 *
 * The build writes `sitemap.xml` and `robots.txt` with `vite-plugin-sitemap`
 * (`vite.config.ts`), which lists every built HTML file — before D6 that
 * was only `/`, the marketing homepage. Now the sitemap carries exactly the
 * platform's indexable pages: contact and the two legal documents. The
 * holding page at `/` is `noindex` and is left out; the retired marketing
 * pages are forwarding addresses and never appear. Academy hosts never see
 * this file: their `robots.txt`/`sitemap.xml` are generated by the backend
 * (B0-WEB-01, see the Caddyfile).
 *
 * Imported by `vite.config.ts`, so this module (and `route-paths.ts`) must
 * stay free of path aliases and browser APIs.
 */
import { PUBLIC_ROUTES } from './route-paths';

/** Indexable platform pages, in the order the sitemap lists them. */
export const PLATFORM_SITEMAP_ROUTES: readonly string[] = [
  PUBLIC_ROUTES.contact,
  PUBLIC_ROUTES.privacyPolicy,
  PUBLIC_ROUTES.terms,
];

/**
 * Built HTML the plugin would list on its own: the holding page's shell,
 * and the scaffold blog index the blog prerender writes (`prerender/`,
 * empty until `seo/content/` has posts) — neither is a page to index.
 */
export const PLATFORM_SITEMAP_EXCLUDED: readonly string[] = [
  PUBLIC_ROUTES.home,
  '/blog',
];
